import { test, expect } from '@playwright/test';

test.describe('Payment Card Declined Error State', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should display clear error message when payment card is declined', async ({ page }) => {
    // Setup: intercept the payment API call
    await page.route('**/api/payment/process', (route) => {
      route.abort('payment declined');
    });

    // Intercept the payment form submission
    await page.route('**/api/payment/submit', (route) => {
      route.abort('payment declined');
    });

    // Verify the payment form is visible
    const paymentForm = page.getByRole('form', { name: /enter payment details/i });
    await expect(paymentForm).toBeVisible();

    // Fill in valid payment details
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('4111111111111111');

    const expiryDateInput = page.getByLabel(/expiry date/i);
    await expiryDateInput.fill('12/25');

    const cvvInput = page.getByLabel(/cvv/i);
    await cvvInput.fill('123');

    // Submit the payment form
    const submitButton = page.getByRole('button', { name: /submit payment/i });
    await submitButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/payment declined/i);
    await expect(errorMessage).toBeVisible();

    // Verify error state is active
    const errorState = page.getByTestId('error-state');
    await expect(errorState).toBeVisible();

    // Verify success message is not visible
    const successMessage = page.getByText(/payment successful/i);
    await expect(successMessage).not.toBeVisible();

    // Verify payment form is still visible
    await expect(paymentForm).toBeVisible();
  });

  test('should handle multiple declined attempts and show retry option', async ({ page }) => {
    // Setup: intercept the payment API call multiple times
    let retryCount = 0;
    await page.route('**/api/payment/process', (route) => {
      if (retryCount < 2) {
        retryCount++;
        route.abort('payment declined');
      } else {
        route.continue();
      }
    });

    // Intercept the payment form submission
    await page.route('**/api/payment/submit', (route) => {
      if (retryCount < 2) {
        retryCount++;
        route.abort('payment declined');
      } else {
        route.continue();
      }
    });

    // Verify the payment form is visible
    const paymentForm = page.getByRole('form', { name: /enter payment details/i });
    await expect(paymentForm).toBeVisible();

    // Fill in valid payment details
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('4111111111111111');

    const expiryDateInput = page.getByLabel(/expiry date/i);
    await expiryDateInput.fill('12/25');

    const cvvInput = page.getByLabel(/cvv/i);
    await cvvInput.fill('123');

    // Submit the payment form
    const submitButton = page.getByRole('button', { name: /submit payment/i });
    await submitButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/payment declined/i);
    await expect(errorMessage).toBeVisible();

    // Verify error state is active
    const errorState = page.getByTestId('error-state');
    await expect(errorState).toBeVisible();

    // Verify retry button is visible
    const retryButton = page.getByRole('button', { name: /retry payment/i });
    await expect(retryButton).toBeVisible();

    // Verify success message is not visible
    const successMessage = page.getByText(/payment successful/i);
    await expect(successMessage).not.toBeVisible();

    // Verify payment form is still visible
    await expect(paymentForm).toBeVisible();

    // Verify retry button is clickable
    await expect(retryButton).toBeEnabled();

    // Click retry button
    await retryButton.click();

    // Verify error message is cleared
    await expect(errorMessage).not.toBeVisible();

    // Verify error state is no longer active
    await expect(errorState).not.toBeVisible();

    // Verify success message is still not visible
    await expect(successMessage).not.toBeVisible();

    // Verify payment form is still visible
    await expect(paymentForm).toBeVisible();
  });
});
